const reviewedCinema = [
  ['style-55', 'renaissance', '文艺复兴人文主义重视古典文化的重新研究及人的理性和能动性，对艺术中的人体、空间与秩序观产生影响。', '它不是单一装饰样式；前端转译要以人的尺度和内容理解为中心，不能只放古典雕像。'],
  ['style-57', 'beauxArts', 'Beaux-Arts 建筑传统联系巴黎美术学院体系，常以轴线、对称和古典构件组织宏大的建筑层级。', '本条指建筑与空间编排传统，不把所有学院绘画归为同一外观。'],
  ['style-58', 'empire', '帝政式在拿破仑时期的法国装饰艺术中发展，以古典权威、胜利象征与严整形体组织陈设。', '符号需服务项目语境，避免把任意黑金配色直接等同帝政式。'],
  ['style-59', 'regency', '摄政式古典主义结合希腊罗马形式，并吸收埃及、自然和部分洛可可装饰，形成多样的室内与家具设计。', '它并非统一的轻盈细线风格；前端应明确选择比例或构件线索。'],
  ['style-73', 'minimalSculpture', '极简雕塑常以简单几何、重复单元和材料本身构成作品，并重视对象与所在空间的关系。', '简化不是减少业务内容，需让比例、间距和体量成为可感知表达。'],
  ['style-80', 'internationalStyle', '国际主义建筑强调体积、表面与规则重复，利用现代结构获得灵活平面和非对称组织，减少附加装饰。', '前端应体现可辨的空间或模块关系，白底无衬线不能独自代表该语言。'],
  ['style-131', 'noir', '黑色电影常以明暗分带、局部反射与压迫性空间表现悬念和不安，视觉与叙事中的暧昧相联系。', '低调照明不等于降低所有文字对比，重要信息须进入清楚亮区。'],
  ['style-132', 'germanFilm', '德国表现主义电影用夸张布景、扭曲空间和强烈阴影表达主观情绪，而非只追求自然再现。', '形变应有明确情绪与层级，不能使必要信息或操作区域失真。'],
  ['style-133', 'neorealism', '意大利新现实主义关注日常社会生活，常借实景、非职业表演与地域性语言产生现场感。', '前端可转译为真实内容与生活尺度；低饱和滤镜本身不等于现实主义。'],
  ['style-134', 'newWave', '法国新浪潮探索个人化电影语言，可采用跳切、灵活摄影和不循传统节奏的叙事。', '跳跃需保留可追踪的内容关系，不能用突然移动控件代替叙事创新。'],
  ['style-135', 'silentFilm', '默片以影像、表演和字幕卡承担主要叙事，不以同步对白为基础；放映仍可伴有音乐。', '黑白是本方案选择，历史默片也有染色；不能用关闭网页声音冒充默片表达。'],
  ['style-136 motion-34', 'silhouetteFilm', '定格动画通过在拍摄的各帧之间移动实物或剪纸，再连续播放产生运动，材料与操作痕迹可形成手作观感。', '数字模拟需有明确姿态和离散帧节奏；卡顿或降低整页帧率不是手工定格。'],
  ['style-138', 'silhouetteFilm', '剪影动画用轮廓清楚的剪纸或其他平面形体逐帧表演，关节、叠层与背景共同承担叙事。', '须让剪影发生可观察动作，静态黑色图标不足以完成动画要求。'],
  ['style-139', 'newHollywood', '新好莱坞时期的电影为导演个人表达及当代社会探索提供空间，人物与结局可突破传统类型的确定性。', '这是广泛的电影实践而非固定色板；界面转译需明确叙事视角且保留操作确定性。'],
  ['motion-13 motion-40', 'dissolve', '交叉叠化让前一画面逐渐消退，同时使后一画面显现，在短时间内共同可见。', '两套内容重叠期间不得重复可操作焦点，结束后清理旧层并维持容器稳定。'],
  ['motion-32', 'frames', '逐帧动画为连续画面分别安排形态或状态，播放次序和每帧时长决定最终运动节奏。', '应验证各帧确有设计差异，不将任意缓动动画命名为逐帧。'],
  ['motion-38', 'matchCut', '图形匹配剪辑利用相邻镜头中相似的形状、位置或构图建立连续或象征关系。', '对应轮廓应在切换前后可辨，简单保持相同背景色并不足够。'],
  ['motion-39', 'matchCut', '动作匹配剪辑通过运动方向、阶段或姿态之间的对应连接镜头，保持动作的可追踪性。', '切换点需与真实动作对应，不能仅给两个无关对象相同动画时长。'],
  ['motion-132', 'matchCut', '匹配剪辑以图形、动作或声音的相似关系连接不同镜头，可产生连贯感或意义联系。', '前端要说明并实现具体匹配对象，交叉淡化本身不构成匹配。'],
  ['motion-41', 'wipe', '划像让一个画面通过移动边界逐步替代另一个，边界可按直线、方向或特定形状推进。', '边界应真实揭示新内容，不能只移动一条装饰线；减少动态时直接显示终态。'],
];
notes.push(...reviewedCinema.map(([ids, source, definition, boundary]) => [ids, source, definition, undefined, boundary]));

